import requests

def test_get_driver_wallet_balances_with_admin_auth():
    base_url = "http://localhost:8000"
    endpoint = "/api/admin/financial/drivers/balances"
    url = base_url + endpoint
    token = "eyJhbGciOiJFUzI1NiIsImtpZCI6ImI4MTI2OWYxLTIxZDgtNGYyZS1iNzE5LWMyMjQwYTg0MGQ5MCIsInR5cCI6IkpXVCJ9..7tnorXc_v1GajgbKOx_eL1YOszeBUfjHR8eD_sTpsMVGd1byScCiaea2NrexKmTDL3dIlmobE5Mqry_s39Blkw"
    headers = {
        "Authorization": f"Bearer {token}",
        "Accept": "application/json"
    }

    try:
        response = requests.get(url, headers=headers, timeout=30)
    except requests.RequestException as e:
        assert False, f"Request failed: {e}"

    assert response.status_code == 200, f"Expected status code 200 but got {response.status_code}"

    try:
        data = response.json()
    except ValueError:
        assert False, "Response is not valid JSON"

    # Validate that data is a list (expected list of driver wallet balances)
    assert isinstance(data, list), f"Expected response data to be a list, got {type(data)}"

    # Optionally validate each item if possible
    # Example minimal validations
    for item in data:
        assert isinstance(item, dict), "Each driver balance record should be a dict"
        assert "driver_id" in item, "Each record should contain 'driver_id'"
        assert "balance" in item, "Each record should contain 'balance'"

test_get_driver_wallet_balances_with_admin_auth()